spec.setup_code:
var TAU = Math.PI * 2;
function mk(s) { return function () { s = s | 0; s = s + 0x6D2B79F5 | 0; var t = Math.imul(s ^ s >>> 15, 1 | s); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
var rng = mk(2024);
function gauss() { var a = rng() + 1e-9, b = rng(); return Math.sqrt(-2 * Math.log(a)) * Math.cos(TAU * b); }
var W0 = [], B0 = [], i;
for (i = 0; i < 12; i++) W0.push(gauss());
for (i = 0; i < 12; i++) B0.push(gauss());
var idx = [];
for (i = 0; i < 12; i++) idx.push(i);
idx.sort(function (a, b) { return Math.abs(W0[a]) - Math.abs(W0[b]); });
var wk = idx.map(function (j) { return W0[j]; });
var bk = idx.map(function (j) { return B0[j]; });
var U0 = -2.1, U1 = 1.4, CYC = 21;
var INK = '#04204B', BLUE = '#0B4FC0', RUST = '#B4552F', SEC = '#3D5F91', FAINT = '#8098BC';
function clamp(x) { return Math.max(0, Math.min(1, x)); }
function ease(x) { x = clamp(x); return x * x * (3 - 2 * x); }
function seg(t, a, b) { return ease((t - a) / (b - a)); }
function lerp(a, b, t) { return a + (b - a) * t; }
function uOf(s) { return 0.25 * Math.log(s / 16); }
function sOf(u) { return 16 * Math.exp(4 * u); }
function fmtS(s) { if (s >= 100) return s.toFixed(0); if (s >= 10) return s.toFixed(1); if (s >= 1) return s.toFixed(2); if (s >= 0.1) return s.toFixed(3); return s.toFixed(4); }
function emb(u) { var v = []; for (var k = 0; k < 12; k++) v.push(Math.cos(TAU * (wk[k] * u + bk[k]))); return v; }
function cosSim(a, b) { var d = 0, na = 0, nb = 0; for (var k = 0; k < 12; k++) { d += a[k] * b[k]; na += a[k] * a[k]; nb += b[k] * b[k]; } return d / Math.sqrt(na * nb + 1e-12); }
var caps = [
  'u = 1/4 ln(sigma / sigma_data): a log scale, so 2560 A and 0.006 A fit on one short axis',
  'each feature is a wave in u with its own random frequency w_k and phase b_k',
  'the values at the cursor are the code the network receives (256 of them in AF3)',
  'a factor 2 apart: similar codes; a factor 10 apart: nearly unrelated codes'
];
var bounds = [0, 3.5, 7.5, 14.5, 21];
var uS10 = uOf(10), uS20 = uOf(20), uS100 = uOf(100);

return {
  draw: function (ctx, width, height, time, dt) {
    ctx.globalAlpha = 1;
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);
    var T = time % CYC;
    var fade = Math.min(1, T / 0.4, (CYC - T) / 0.4);
    function setA(a) { ctx.globalAlpha = clamp(a) * fade; }
    var px = 74, pr = 14, pw = width - px - pr;
    function X(u) { return px + (u - U0) / (U1 - U0) * pw; }
    var stripTop = 0.12 * height, stripH = 0.40 * height / 12;
    var ya = stripTop + 12 * stripH + 6;
    var ly = 0.645 * height, base = 0.79 * height, amp = 0.095 * height;
    var klab = 0.93 * height, simY = 0.975 * height;
    ctx.font = '12px sans-serif';
    ctx.textBaseline = 'alphabetic';

    // caption
    var ph = T < bounds[1] ? 0 : T < bounds[2] ? 1 : T < bounds[3] ? 2 : 3;
    var cs = bounds[ph], ce = bounds[ph + 1];
    var ca = Math.min(seg(T, cs, cs + 0.4), 1 - seg(T, ce - 0.4, ce));
    if (ph === 0) ca = Math.max(ca, 1 - seg(T, 0, 0.01) * 0 ) * 1;
    var words = caps[ph].split(' ');
    var maxW = width - 20, lines = [caps[ph]];
    if (ctx.measureText(caps[ph]).width > maxW) {
      var best = 1e9, bi = 1;
      for (i = 1; i < words.length; i++) {
        var l1 = ctx.measureText(words.slice(0, i).join(' ')).width;
        var l2 = ctx.measureText(words.slice(i).join(' ')).width;
        if (Math.max(l1, l2) < best) { best = Math.max(l1, l2); bi = i; }
      }
      lines = [words.slice(0, bi).join(' '), words.slice(bi).join(' ')];
    }
    setA(ca);
    ctx.fillStyle = INK; ctx.textAlign = 'center';
    for (i = 0; i < lines.length; i++) ctx.fillText(lines[i], width / 2, 16 + i * 15);

    // axis
    var axA = seg(T, 0, 1.2);
    setA(axA);
    ctx.strokeStyle = SEC; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(X(U0), ya); ctx.lineTo(X(U1), ya); ctx.stroke();
    var tk = [0.01, 0.1, 1, 10, 100, 1000], tl = ['0.01', '0.1', '1', '10', '100', '1000'];
    ctx.textAlign = 'center';
    for (i = 0; i < tk.length; i++) {
      var tx = X(uOf(tk[i]));
      setA(axA);
      ctx.strokeStyle = SEC;
      ctx.beginPath(); ctx.moveTo(tx, ya); ctx.lineTo(tx, ya + 4); ctx.stroke();
      setA(axA * 0.3);
      ctx.strokeStyle = FAINT;
      ctx.beginPath(); ctx.moveTo(tx, stripTop); ctx.lineTo(tx, ya); ctx.stroke();
      setA(axA);
      ctx.fillStyle = SEC;
      ctx.fillText(tl[i], tx, ya + 16);
    }
    setA(axA);
    ctx.fillStyle = SEC; ctx.textAlign = 'left';
    ctx.fillText('σ (Å)', 8, ya + 16);
    ctx.textAlign = 'center'; ctx.fillStyle = INK;
    ctx.fillText('u = ¼ ln(σ/16)', px + pw / 2, ya + 30);

    // endpoint markers (phase 1)
    var epA = seg(T, 1.0, 2.0) * (1 - seg(T, 7.5, 8.5));
    var xS = X(uOf(2560)), xE = X(uOf(0.0064));
    setA(epA);
    ctx.strokeStyle = RUST; ctx.lineWidth = 1.5; ctx.setLineDash([4, 3]);
    ctx.beginPath(); ctx.moveTo(xE, stripTop - 2); ctx.lineTo(xE, ya + 4); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = RUST;
    ctx.textAlign = 'left'; ctx.fillText('0.0064 Å', xE - 2, ya + 30);
    var startA = Math.max(seg(T, 1.0, 2.0), seg(T, 7.0, 7.5));
    setA(epA);
    ctx.textAlign = 'right'; ctx.fillText('2560 Å', xS + 3, ya + 30);

    // strips
    for (var k = 0; k < 12; k++) {
      var cy = stripTop + (k + 0.5) * stripH, a = stripH * 0.42;
      var p = seg(T, 3.5 + k * 0.12, 4.9 + k * 0.12);
      if (p <= 0) continue;
      setA(p);
      ctx.strokeStyle = FAINT; ctx.lineWidth = 0.6;
      ctx.beginPath(); ctx.moveTo(px, cy); ctx.lineTo(px + pw, cy); ctx.stroke();
      ctx.fillStyle = SEC; ctx.textAlign = 'right'; ctx.font = '11px sans-serif';
      ctx.fillText('w' + (k + 1) + '=' + wk[k].toFixed(2), px - 6, cy + 4);
      ctx.font = '12px sans-serif';
      var n = Math.max(2, Math.floor(110 * p));
      ctx.strokeStyle = BLUE; ctx.lineWidth = 1.2;
      ctx.beginPath();
      for (i = 0; i <= n; i++) {
        var uu = U0 + (U1 - U0) * p * i / n;
        var yy = cy - a * Math.cos(TAU * (wk[k] * uu + bk[k]));
        if (i === 0) ctx.moveTo(X(uu), yy); else ctx.lineTo(X(uu), yy);
      }
      ctx.stroke();
    }

    // cursors
    var dual = seg(T, 14.5, 15.2);
    var uA, uB = uS20;
    if (T < 14.5) uA = lerp(uOf(2560), uOf(0.0064), ease((T - 7.5) / 6.5));
    else uA = lerp(uOf(0.0064), uS10, seg(T, 14.5, 15.6));
    uB = lerp(uS20, uS100, seg(T, 17.8, 18.8));
    var curA = clamp((T - 7.2) / 0.3);
    var curB = seg(T, 14.8, 15.6);
    var cursors = [];
    if (curA > 0) cursors.push({ u: uA, col: T < 14.5 ? RUST : INK, al: curA });
    if (curB > 0) cursors.push({ u: uB, col: RUST, al: curB });
    for (var c = 0; c < cursors.length; c++) {
      var cu = cursors[c], cx = X(cu.u);
      setA(cu.al);
      ctx.strokeStyle = cu.col; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(cx, stripTop - 3); ctx.lineTo(cx, ya + 5); ctx.stroke();
      var ev = emb(cu.u);
      for (k = 0; k < 12; k++) {
        ctx.fillStyle = ev[k] >= 0 ? BLUE : RUST;
        ctx.beginPath(); ctx.arc(cx, stripTop + (k + 0.5) * stripH - stripH * 0.42 * ev[k], 2.6, 0, TAU); ctx.fill();
      }
    }

    // bars
    function drawBars(x0, w, u, al, sparse) {
      var v = emb(u);
      setA(al);
      ctx.strokeStyle = FAINT; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(x0, base); ctx.lineTo(x0 + w, base); ctx.stroke();
      var bw = w / 12 * 0.58;
      for (var j = 0; j < 12; j++) {
        var bx = x0 + (j + 0.5) * w / 12;
        ctx.fillStyle = v[j] >= 0 ? BLUE : RUST;
        ctx.fillRect(bx - bw / 2, v[j] >= 0 ? base - v[j] * amp : base, bw, Math.max(1, Math.abs(v[j]) * amp));
        if (!sparse || j === 0 || j === 5 || j === 11) {
          ctx.fillStyle = SEC; ctx.textAlign = 'center'; ctx.font = '11px sans-serif';
          ctx.fillText('' + (j + 1), bx, klab);
          ctx.font = '12px sans-serif';
        }
      }
      return v;
    }
    var barsA = seg(T, 7.2, 8.0);
    var sA = barsA * (1 - dual);
    if (barsA > 0) {
      setA(barsA);
      ctx.fillStyle = SEC; ctx.textAlign = 'right'; ctx.font = '11px sans-serif';
      ctx.fillText('+1', px - 6, base - amp + 4);
      ctx.fillText('-1', px - 6, base + amp + 4);
      ctx.fillText('n_k', px - 6, base + 4);
      ctx.font = '12px sans-serif';
    }
    if (sA > 0.01) {
      drawBars(px, pw, uA, sA, false);
      setA(sA);
      ctx.fillStyle = INK; ctx.textAlign = 'left';
      ctx.fillText('n_k = cos(2π(w_k u + b_k))', px, ly);
      ctx.textAlign = 'right'; ctx.fillStyle = RUST;
      ctx.fillText('σ = ' + fmtS(sOf(uA)) + ' Å', px + pw, ly);
      ctx.fillStyle = SEC; ctx.textAlign = 'center';
      ctx.fillText('feature index k', px + pw / 2, simY);
    }
    if (dual > 0.01) {
      var gw = (pw - 16) / 2, xB = px + gw + 16;
      var vA = drawBars(px, gw, uA, dual, true);
      var vB = drawBars(xB, gw, uB, dual * curB, true);
      setA(dual * 0.6);
      ctx.strokeStyle = FAINT; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(px + gw + 8, ly - 10); ctx.lineTo(px + gw + 8, klab + 4); ctx.stroke();
      setA(dual);
      ctx.textAlign = 'left'; ctx.fillStyle = INK;
      ctx.fillText('σ = ' + fmtS(sOf(uA)) + ' Å', px, ly);
      setA(dual * curB);
      ctx.fillStyle = RUST;
      ctx.fillText('σ = ' + fmtS(sOf(uB)) + ' Å', xB, ly);
      var sa = dual * seg(T, 15.6, 16.2);
      setA(sa);
      ctx.fillStyle = INK; ctx.textAlign = 'center';
      ctx.fillText('σ ratio ' + (sOf(uB) / sOf(uA)).toFixed(1) + '   cosine similarity ' + cosSim(vA, vB).toFixed(2), px + pw / 2, simY);
    }
    ctx.globalAlpha = 1;
  }
};
